}

// prmpt -- wiring the status line into Claude Code.
//
// Claude Code documents an external-command status line, so this whole surface
// is one config edit and nothing else. Nothing here patches, repacks or
// re-signs an application; the plugin owns one key in one file it is invited to
// write, and `uninstall` puts it back.
//
//   ~/.claude/settings.json   "statusLine": { type: "command", command: ... }
//
// Two rules govern the edit:
//
//   - Chain, never clobber. A status line someone configured themselves is not
//     ours to delete. Whatever was there is stashed and run by our renderer,
//     with its output kept above ours.
//   - It is reversible. The pre-install value is recorded once, at first
//     install, and restored verbatim on uninstall.
//
// Codex is deliberately absent. Its `[tui] status_line` accepts identifiers
// from a closed set of built-in items -- `model-with-reasoning`, `current-dir`,
// `git-branch`, `context-used` and so on -- and cannot run a command at all.
// Verified against the codex 0.150.1 binary: there is a validation path
// reporting "configuration contains unknown item identifiers", and the
// `status_line_timeout_ms` key that a competing implementation writes does not
// exist in the binary. openai/codex#17827 is the open feature request for
// command-backed status lines; #20244 was closed as its duplicate.
//
// Writing an argv there would produce startup warnings and render nothing. This
// is exactly the failure CLAUDE.md warns about, so it is recorded rather than
// attempted. Codex is otherwise unaffected: its `Stop` hook still supplies turn
// text, still gets a match, still prints the end-of-turn line, and still parks
// a slot -- which the VS Code / Cursor extension can render even though Codex
// itself has nowhere to put it.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { configDir } from './config.mjs';
import { pluginRoot } from './version.mjs';

/**
 * Recognises our own command so a re-install doesn't chain itself.
 *
 * Anchored on the directory as well as the file name, and duplicated verbatim
 * in the merge programs install.sh and install.ps1 embed -- both routes write
 * this setting and either may find the other's work. A bare 'statusline.mjs'
 * also matches somebody's own their-statusline.mjs, and mistaking theirs for
 * ours means either deleting it on uninstall or forking a fresh copy of the
 * renderer on every single render.
 */
const MARKER = /hooks[\/\\]statusline\.mjs/;

/** Is this status-line command one of ours? */
export function isOurCommand(command) {
  return typeof command === 'string' && MARKER.test(command);
}

/**
 * What installing costs the user, printed before anything is written.
 *
 * Claude Code drops most of its footer keyboard hints -- `esc to interrupt`
 * among them -- as soon as a custom status line exists. That is a real trade
 * and the user has to make it knowingly, which is also why this surface is
 * opt-in and is not wired in by install.sh.
 */
export const CLAUDE_TRADE_OFF = [
  'Claude Code hides most of its footer keyboard hints -- including',
  '"esc to interrupt" -- whenever a custom status line is configured.',
  'That is Claude Code behaviour, not something prmpt chooses.',
  "Run 'prmpt statusline uninstall' to get them back.",
];

export function claudeSettingsPath() {
  return path.join(os.homedir(), '.claude', 'settings.json');
}

function backupDir() {
  return path.join(configDir(), 'statusline-backup');
}

function chainPath(host) {
  return path.join(configDir(), `statusline-chain-${host}.json`);
}

function readJson(file) {
  try {
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function writeJson(file, value, mode = 0o600) {
  fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`, { mode });
}

/** Every host that has ever had a chain file, most likely first. */
const CHAIN_HOSTS = ['claude', 'codex'];

/**
 * The chained status line, if the renderer should run one.
 *
 * Keyed by host so that a machine running more than one agent keeps them
 * separate. Only Claude Code can install today, but the renderer is written
 * against the general case.
 *
 * The fallback across hosts is load-bearing rather than tidy-minded: the host
 * is guessed from CLAUDECODE, and only one of these files is ever written on a
 * machine, so taking whichever exists cannot pick the wrong one.
 *
 * UNVERIFIED ASSUMPTION, and a judgement call rather than a fact: CLAUDECODE=1
 * is documented for HOOKS, and nothing says it is set for the status-line
 * command as well. It was not confirmed against a running Claude Code. If it
 * turns out not to be set, the guess here is wrong every time -- which without
 * the fallback would mean silently never running a status line somebody built,
 * the one failure in this file that costs a user something they made. If you
 * confirm the behaviour either way, say so here and simplify accordingly.
 */
export function readChain(host = process.env.CLAUDECODE === '1' ? 'claude' : 'codex') {
  for (const candidate of [host, ...CHAIN_HOSTS]) {
    const found = readJson(chainPath(candidate));
    if (found) return found;
  }
  return null;
}

/** The command Claude Code should run, quoted for a path with spaces in it. */
export function renderCommand() {
  return `node "${path.join(pluginRoot(), 'hooks', 'statusline.mjs')}"`;
}

/**
 * The UserPromptSubmit hook that fetches something fresher for the row.
 *
 * Part of THIS surface, not of the default install: it exists only to fill the
 * status-line slot, so wiring it without a status line would send keywords
 * derived from somebody's prompt for an ad that had nowhere to appear.
 * install.sh --statusline writes the same pair.
 */
export function fetchCommand() {
  return `node "${path.join(pluginRoot(), 'hooks', 'prompt-start.mjs')}"`;
}

/** Recognises the fetch hook, ours or a previous version of ours. */
function isOurFetchHook(entry) {
  return typeof entry?.command === 'string' && /prompt-start\.mjs/.test(entry.command);
}

/**
 * Add our UserPromptSubmit entry, replacing any earlier copy of it.
 *
 * Filtering first is what stops a re-install stacking duplicates: the settings
 * file is the user's and we are one entry in a list that may hold several.
 */
function addFetchHook(settings) {
  const hooks = settings.hooks && typeof settings.hooks === 'object' ? settings.hooks : {};
  const groups = Array.isArray(hooks.UserPromptSubmit) ? hooks.UserPromptSubmit : [];
  const kept = [];
  for (const group of groups) {
    if (!Array.isArray(group?.hooks)) { kept.push(group); continue; }
    const remaining = group.hooks.filter((h) => !isOurFetchHook(h));
    if (remaining.length) kept.push({ ...group, hooks: remaining });
  }
  // Timeout in SECONDS. Claude Code and Gemini CLI differ on the unit and the
  // two are not interchangeable.
  kept.push({ hooks: [{ type: 'command', command: fetchCommand(), timeout: 5 }] });
  settings.hooks = { ...hooks, UserPromptSubmit: kept };
}

/** Take our UserPromptSubmit entry back out, leaving everybody else's. */
function removeFetchHook(settings) {
  const groups = settings.hooks?.UserPromptSubmit;
  if (!Array.isArray(groups)) return;
  const kept = [];
  for (const group of groups) {
    if (!Array.isArray(group?.hooks)) { kept.push(group); continue; }
    const remaining = group.hooks.filter((h) => !isOurFetchHook(h));
    if (remaining.length) kept.push({ ...group, hooks: remaining });
  }
  if (kept.length) settings.hooks.UserPromptSubmit = kept;
  else delete settings.hooks.UserPromptSubmit;
  if (Object.keys(settings.hooks).length === 0) delete settings.hooks;
}

// --- Claude Code ------------------------------------------------------------

export function claudeStatus() {
  const settings = readJson(claudeSettingsPath());
  const command = settings?.statusLine?.command;
  return {
    host: 'claude-code',
    path: claudeSettingsPath(),
    supported: true,
    present: fs.existsSync(claudeSettingsPath()),
    installed: isOurCommand(command),
    chained: readJson(chainPath('claude')) !== null,
  };
}

export function installClaude() {
  const file = claudeSettingsPath();
  const settings = readJson(file) || {};

  // One pristine backup, taken before the first edit and never overwritten --
  // a second install after an uninstall must not record our own value as the
  // thing to restore to.
  const backup = path.join(backupDir(), 'claude.settings.json');
  if (!fs.existsSync(backup)) writeJson(backup, settings);

  const existing = settings.statusLine;
  const isOurs = Boolean(existing) && isOurCommand(existing.command);
  if (existing && !isOurs) {
    writeJson(chainPath('claude'), existing);
  } else if (!existing) {
    try { fs.rmSync(chainPath('claude'), { force: true }); } catch { /* ignore */ }
  }

  // No `refreshInterval`. Claude Code already re-runs the command on events,
  // and the end of a turn is one of them -- which is the only moment our slot
  // can change. An interval on top of that would spawn a process every few
  // seconds for the life of every session and never find anything new.
  settings.statusLine = {
    type: 'command',
    command: renderCommand(),
    padding: 0,
  };

  // The surface is both halves, so both go in together.
  addFetchHook(settings);

  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify(settings, null, 2)}\n`);
  return { path: file, chained: existing && !isOurs ? existing : null };
}

export function uninstallClaude() {
  const file = claudeSettingsPath();
  const settings = readJson(file);
  if (!settings) return { path: file, changed: false };

  const command = settings.statusLine?.command;
  if (typeof command === 'string' && !isOurCommand(command)) {
    // Someone else's status line is in place now. Leave it entirely alone.
    return { path: file, changed: false };
  }

  const chain = readJson(chainPath('claude'));
  if (chain) settings.statusLine = chain;
  else delete settings.statusLine;

  // Both halves came in together and both go out together. Leaving the fetch
  // hook behind would keep sending prompt keywords for a row that no longer
  // exists -- the exact trade the user just opted out of.
  removeFetchHook(settings);

  fs.writeFileSync(file, `${JSON.stringify(settings, null, 2)}\n`);
  try { fs.rmSync(chainPath('claude'), { force: true }); } catch { /* ignore */ }
  return { path: file, changed: true, restored: chain || null };
}

// --- reporting --------------------------------------------------------------

/**
 * Why Codex cannot have this surface, carried in the status output so the
 * answer is one command away rather than a thing somebody rediscovers by
 * writing a config that silently does nothing.
 */
export function codexStatus() {
  return {
    host: 'codex',
    path: path.join(os.homedir(), '.codex', 'config.toml'),
    supported: false,
    reason: '[tui] status_line takes built-in item ids, not a command (openai/codex#17827)',
    note: 'Codex still serves ads through its Stop hook, and its turns still park a slot.',
  };
}

/** Which hosts are present on this machine and can actually be installed into. */
export function detectHosts() {
  const hosts = [];
  if (fs.existsSync(path.dirname(claudeSettingsPath()))) hosts.push('claude');
  return hosts;
}

export function statusAll() {
  return [claudeStatus(), codexStatus()];
}

// prmpt -- the backend GraphQL client.
//
// Used by the end-of-turn hook and the interactive wallet/dashboard commands.
// serveAd never throws: it resolves to null on any failure at all, because a
// failed ad request must be indistinguishable from "no ad matched".

import { currentVersion } from './version.mjs';

const SERVE_AD = `mutation ServeAd($input: TurnContextInput!) {
  serveAd(input: $input) {
    requestId
    headline
    body
    clickUrl
  }
}`;

// The status-line surface bills on RENDER, not on the serve.
//
// A decision fetched at the start of a turn may never be shown -- the turn can
// end before the status line repaints, or the user can have the slot expire
// under them -- so the serve alone is not an impression. The renderer records
// what it actually drew and this mutation reports the batch, always from a
// detached child and never from the render path.
const CONFIRM_IMPRESSIONS = `mutation ConfirmImpressions($requestIds: [ID!]!) {
  confirmImpressions(requestIds: $requestIds)
}`;

// Sign-In With Solana, the two halves of one round trip.
//
// The signature must cover the server's `message` BYTE FOR BYTE. Rebuilding
// the text client-side from its visible parts is the classic way to fail this:
// the domain, the chain id and the issued-at timestamp all come from server
// configuration, and a single character of drift verifies against nothing.
const SIWS_CHALLENGE = `mutation SiwsChallenge($wallet: String!) {
  siwsChallenge(wallet: $wallet) {
    wallet
    nonce
    message
    expiresAt
  }
}`;

// Sign-In With Ethereum, for the Base half of the wallet.
//
// This is a LINK, not a login: the user is already authenticated by the
// SIWS pair above, and this attaches the second address they hold. Which is why
// linkEvmWallet needs the token and evmChallenge does not.
const EVM_CHALLENGE = `mutation EvmChallenge($address: String!) {
  evmChallenge(address: $address) {
    address
    nonce
    message
    expiresAt
  }
}`;

const LINK_EVM_WALLET = `mutation LinkEvmWallet($address: String!, $nonce: String!, $signature: String!) {
  linkEvmWallet(address: $address, nonce: $nonce, signature: $signature) {
    installId
    solanaWallet
    evmWallet
    payoutToken
    payoutChain
  }
}`;

// The dashboard route out of the terminal: mint a one-off code and open it.
//
// The plugin proves its locally held wallet and hands a short-lived code to the
// browser, so the dashboard can open without moving the key.
const CREATE_WEB_SESSION = `mutation CreateWebSession {
  createWebSession {
    code
    url
    expiresAt
  }
}`;

const SIWS_VERIFY = `mutation SiwsVerify($wallet: String!, $nonce: String!, $signature: String!) {
  siwsVerify(wallet: $wallet, nonce: $nonce, signature: $signature) {
    token
    expiresAt
    user {
      installId
      solanaWallet
      evmWallet
      payoutToken
      payoutChain
    }
  }
}`;

/**
 * One GraphQL POST with a hard deadline.
 *
 * The AbortController is the only timeout that matters: fetch's own socket
 * timeouts are far too generous for something sitting in the user's turn
 * latency. The timer is unref'd so a resolved request never keeps the process
 * alive waiting for it.
 */
async function graphql({ endpoint, token, query, variables, timeoutMs = 1500 }) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  if (typeof timer.unref === 'function') timer.unref();

  try {
    const headers = {
      'content-type': 'application/json',
      accept: 'application/json',
      'user-agent': `prmpt-plugin/${currentVersion()}`,
    };
    if (token) headers.authorization = `Bearer ${token}`;

    const res = await fetch(endpoint, {
      method: 'POST',
      headers,
      body: JSON.stringify({ query, variables }),
      signal: controller.signal,
    });

    if (!res.ok) {
      // Drain so the socket can be reused/closed rather than left dangling.
      await res.text().catch(() => {});
      const err = new Error(`prmpt: HTTP ${res.status}`);
      err.status = res.status;
      throw err;
    }

    const json = await res.json();
    if (json && Array.isArray(json.errors) && json.errors.length > 0) {
      const err = new Error(json.errors[0]?.message || 'prmpt: GraphQL error');
      err.graphQLErrors = json.errors;
      throw err;
    }
    return json?.data ?? null;
  } finally {
    clearTimeout(timer);
  }
}

/** Derive http://host/c/{requestId} from the GraphQL endpoint. */
function fallbackClickUrl(endpoint, requestId) {
  try {
    return new URL(`/c/${encodeURIComponent(requestId)}`, endpoint).toString();
  } catch {
    return null;
  }
}

/**
 * Ask the backend for an ad for this turn.
 *
 * Resolves to a normalised decision or to null. Never rejects, never logs, and
 * never lets an error escape into the user's session -- that is the entire
 * contract this function exists to uphold.
 */
export async function serveAd(config, input) {
  try {
    const data = await graphql({
      endpoint: config.endpoint,
      token: config.token,
      query: SERVE_AD,
      variables: { input },
      timeoutMs: config.timeoutMs,
    });

    const ad = data?.serveAd;
    if (!ad || typeof ad !== 'object') return null;

    const headline = typeof ad.headline === 'string' ? ad.headline.trim() : '';
    const requestId = typeof ad.requestId === 'string' ? ad.requestId.trim() : '';
    if (!headline || !requestId) return null;

    const clickUrl =
      (typeof ad.clickUrl === 'string' && ad.clickUrl.trim()) ||
      fallbackClickUrl(config.endpoint, requestId);
    if (!clickUrl) return null;

    return {
      requestId,
      headline,
      body: typeof ad.body === 'string' ? ad.body.trim() : '',
      clickUrl,
    };
  } catch {
    // Timeout, connection refused, bad JSON, GraphQL error, anything: no ad.
    return null;
  }
}

/**
 * Report the impressions that have actually been rendered.
 *
 * Resolves to the number the backend accepted, or null on any failure at all --
 * the caller keeps the ids and retries on a later turn, so a flush that fails
 * costs nothing but a delay. Never rejects: this runs in a detached child with
 * nowhere to report to.
 */
export async function confirmImpressions(config, requestIds) {
  if (!Array.isArray(requestIds) || requestIds.length === 0) return 0;
  try {
    const data = await graphql({
      endpoint: config.endpoint,
      token: config.token,
      query: CONFIRM_IMPRESSIONS,
      variables: { requestIds },
      timeoutMs: config.timeoutMs,
    });
    const n = data?.confirmImpressions;
    return typeof n === 'number' ? n : null;
  } catch {
    return null;
  }
}

/**
 * Ask for a one-time SIWE challenge over an EVM address.
 *
 * Anonymous, like its Solana counterpart: minting a challenge proves nothing.
 */
export async function evmChallenge({ endpoint, address, timeoutMs = 15000 }) {
  const data = await graphql({
    endpoint,
    query: EVM_CHALLENGE,
    variables: { address },
    timeoutMs,
  });

  const node = data?.evmChallenge;
  if (!node || typeof node.message !== 'string' || typeof node.nonce !== 'string') {
    throw new Error('prmpt: evmChallenge returned no challenge');
  }
  return {
    address: typeof node.address === 'string' ? node.address : address,
    nonce: node.nonce,
    message: node.message,
    expiresAt: typeof node.expiresAt === 'string' ? node.expiresAt : null,
  };
}

/**
 * Attach the proven Base address to this install's user account.
 *
 * Needs the user token: the backend takes the account from the token and
 * never from the address, so this can only ever link to us.
 */
export async function linkEvmWallet({ endpoint, token, address, nonce, signature, timeoutMs = 15000 }) {
  const data = await graphql({
    endpoint,
    token,
    query: LINK_EVM_WALLET,
    variables: { address, nonce, signature },
    timeoutMs,
  });

  const node = data?.linkEvmWallet;
  if (!node || typeof node !== 'object') {
    throw new Error('prmpt: linkEvmWallet returned no user');
  }
  return {
    installId: node.installId ?? null,
    solanaWallet: node.solanaWallet ?? null,
    evmWallet: node.evmWallet ?? null,
    payoutToken: node.payoutToken ?? null,
    payoutChain: node.payoutChain ?? null,
  };
}

/** Mint a one-off code that opens the dashboard as this install's user. */
export async function createWebSession({ endpoint, token, timeoutMs = 15000 }) {
  const data = await graphql({ endpoint, token, query: CREATE_WEB_SESSION, timeoutMs });

  const node = data?.createWebSession;
  if (!node || typeof node.url !== 'string' || !node.url) {
    throw new Error('prmpt: createWebSession returned no url');
  }
  return {
    code: typeof node.code === 'string' ? node.code : null,
    url: node.url,
    expiresAt: typeof node.expiresAt === 'string' ? node.expiresAt : null,
  };
}

/**
 * Ask for a one-time SIWS challenge to sign.
 *
 * Throws because every caller is a person running a command and waiting for
 * it, so a failure has to be legible.
 */
export async function siwsChallenge({ endpoint, wallet, timeoutMs = 15000 }) {
  const data = await graphql({
    endpoint,
    query: SIWS_CHALLENGE,
    variables: { wallet },
    timeoutMs,
  });

  const node = data?.siwsChallenge;
  if (!node || typeof node.message !== 'string' || typeof node.nonce !== 'string') {
    throw new Error('prmpt: siwsChallenge returned no challenge');
  }
  return {
    wallet: typeof node.wallet === 'string' ? node.wallet : wallet,
    nonce: node.nonce,
    message: node.message,
    expiresAt: typeof node.expiresAt === 'string' ? node.expiresAt : null,
  };
}

/**
 * Hand back the signature and take the user JWT.
 *
 * The nonce is consumed by the backend before the signature is even checked, so
 * a failure here burns the challenge. Retrying means minting a fresh one, which
 * is why the login command runs both halves rather than exposing them apart.
 */
export async function siwsVerify({ endpoint, wallet, nonce, signature, timeoutMs = 15000 }) {
  const data = await graphql({
    endpoint,
    query: SIWS_VERIFY,
    variables: { wallet, nonce, signature },
    timeoutMs,
  });

  const node = data?.siwsVerify;
  if (!node || typeof node.token !== 'string' || !node.token) {
    throw new Error('prmpt: siwsVerify returned no token');
  }
  return {
    token: node.token,
    expiresAt: typeof node.expiresAt === 'string' ? node.expiresAt : null,
    installId: node.user?.installId ?? null,
    solanaWallet: node.user?.solanaWallet ?? null,
    evmWallet: node.user?.evmWallet ?? null,
    payoutToken: node.user?.payoutToken ?? null,
    payoutChain: node.user?.payoutChain ?? null,
  };
}

// The Amp plugin is TypeScript for Bun and cannot be executed under plain
// node, and the suite is dependency-free so there is no transpiler to reach
// for. These are therefore static source assertions -- deliberately narrow,
// and aimed at the two traps the file's own header documents, because both
// are silent in production: one starts an extra turn, the other reads the
// user's prompt and sends it to the ad backend as if it were the reply.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

import { PLUGIN_DIR } from './helpers.mjs';

const AMP = path.join(PLUGIN_DIR, 'amp', 'prmpt.ts');
const src = fs.readFileSync(AMP, 'utf8');

/** The source with comments stripped, so prose about a trap is not the trap. */
const code = src
  .replace(/\/\*[\s\S]*?\*\//g, '')
  .replace(/^[ \t]*\/\/.*$/gm, '');

test('the agent.end handler never returns an action (which would start another turn)', () => {
  // Any `action:` in a returned object -- `{ action: 'continue' }` and friends
  // -- makes Amp run the agent again, turning one sponsored line into an
  // infinite loop of them.
  assert.ok(
    !/\baction\s*:/.test(code),
    'amp/prmpt.ts must never return an `action`; that would start another turn',
  );
  assert.ok(
    !/return\s*\{/.test(code),
    'the agent.end handler must only ever `return` bare (early-exit), never a value',
  );
});

test('it reads event.messages, not event.message', () => {
  // `event.message` is the USER'S prompt that started the turn. Sending that
  // as the turn text would both mis-target the ad and transmit user input.
  assert.ok(/\.messages\b/.test(code), 'amp/prmpt.ts must read event.messages');
  assert.ok(
    !/\bevent\s*(?:as[^)]*\)?)?\s*\.message\b(?!s)/.test(code),
    'amp/prmpt.ts must not read event.message (that is the user prompt)',
  );
  assert.ok(
    !/\bmessage\b(?!s)\s*:/.test(code.replace(/messages\?:/g, '')),
    'no `message` property should be destructured or typed off the event',
  );
});

test('it stays silent on failure and honours the shared opt-outs', () => {
  assert.ok(/catch\s*\{/.test(code) || /catch\s*\(/.test(code), 'the handler must swallow errors');
  assert.ok(/PRMPT_DISABLED/.test(code), 'the opt-out must be honoured here too');
  assert.ok(/AbortSignal\.timeout\(\s*TIMEOUT_MS\s*\)/.test(code), 'the request must have a deadline');
  assert.ok(/const TIMEOUT_MS = 1500/.test(code), 'the deadline must match the hook (1500ms)');
  assert.ok(/const MIN_TURN_CHARS = 80/.test(code));
  assert.ok(/const MAX_TURN_CHARS = 4000/.test(code));
});

test('it only ever looks at assistant messages', () => {
  assert.ok(/role\s*!==\s*'assistant'/.test(code), 'non-assistant messages must be skipped');
  assert.ok(/type\s*===\s*'text'/.test(code), 'only text blocks are read; no thinking blocks');
  assert.ok(!/'thinking'/.test(code), 'thinking blocks must never be gathered');
});

test('it does not write to stdout or stderr', () => {
  // Amp surfaces the block through ctx.ui.notify; a console write would land
  // in the middle of the user's session.
  assert.ok(!/console\.(log|error|warn|info)/.test(code));
  assert.ok(!/process\.std(out|err)\.write/.test(code));
  assert.ok(/ctx\.ui\.notify/.test(code));
});

test('it declares which ad surface it is serving', () => {
  // The backend now has two: the end-of-turn line every host gets, and Claude
  // Code's status line. Amp has no status line, so this file is TURN_END and
  // nothing else -- and it has its own inlined copy of the request, so the
  // field has to be added here separately from hooks/lib/api.mjs.
  assert.ok(/surface:\s*'TURN_END'/.test(code), "amp/prmpt.ts must send surface: 'TURN_END'");
  assert.ok(!/STATUS_LINE/.test(code), 'Amp has no status line and must never ask for one');
});

test('it never sends signalTokens, because it has the real turn text', () => {
  assert.ok(!/signalTokens/.test(code));
});

// Which status-line ads are billed, and how many times.
//
// The slot has two fillers and only one of them owes an impression:
//
//   turn-end  the ad the end-of-turn request already served AND already
//             billed. Re-displayed from disk, costing nothing and earning
//             nothing. Billing it here would charge the advertiser twice for
//             one decision -- silently, and visible only as inflated spend.
//   prompt    a decision fetched for THIS surface by hooks/slot-fetch.mjs. It
//             has been billed nowhere, so the first render owes exactly one
//             impression and every render after it owes none.
//
// Claude Code re-runs the status-line command continuously while the model
// works, so "exactly once" is not a formality: the naive version bills one
// decision hundreds of times in a single turn.
//
// The renderer cannot report anything itself -- it may not touch the network --
// so what it does is append to pending.jsonl. That file IS the bill, and it is
// what these tests read.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

import { baseEnv, configDirOf, runStatusLine, tmpDir } from './helpers.mjs';

const SESSION = 'sess-billing';

const AD = {
  requestId: 'req_bill_1',
  headline: 'Quarantine flaky tests automatically',
  body: 'Detects flakes from CI history.',
  clickUrl: 'https://ads.example/c/req_bill_1',
};

/** A sandbox HOME with one slot parked by the named filler. */
function parked(filler, over = {}) {
  const home = tmpDir('prmpt-bill-home-');
  const dir = configDirOf(home);
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  fs.writeFileSync(
    path.join(dir, 'slot.json'),
    `${JSON.stringify({ ...AD, sessionId: SESSION, harness: 'claude-code', filler, ts: Date.now(), ...over })}\n`,
    { mode: 0o600 },
  );
  return { home, pending: path.join(dir, 'pending.jsonl') };
}

/** Draw the status line the way Claude Code does, `times` over. */
async function draw(home, times = 1) {
  const rendered = [];
  for (let i = 0; i < times; i++) {
    const res = await runStatusLine({
      stdin: JSON.stringify({ session_id: SESSION, model: { display_name: 'Opus' } }),
      env: baseEnv({ HOME: home, CLAUDECODE: '1' }),
    });
    assert.equal(res.code, 0, `render ${i} exited ${res.code}: ${res.stderr}`);
    assert.equal(res.stderr, '', `render ${i} wrote to stderr`);
    rendered.push(res.stdout);
  }
  return rendered;
}

/** Every requestId the renderer has queued for confirmImpressions. */
function billed(pending) {
  if (!fs.existsSync(pending)) return [];
  return fs
    .readFileSync(pending, 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line).requestId);
}

test('a parked turn-end ad is rendered but never billed as a status-line impression', async () => {
  // The whole point of the parked filler: it costs nothing and it is free. The
  // end-of-turn request already paid for this decision.
  const { home, pending } = parked('turn-end');

  const rendered = await draw(home, 5);
  for (const [i, out] of rendered.entries()) {
    assert.ok(out.includes(AD.headline), `render ${i} drew nothing -- the fallback must still show`);
  }

  assert.deepEqual(
    billed(pending),
    [],
    'a parked ad was billed a second time on the status line',
  );
});

test('a prompt-fetched ad is billed exactly once, however many times it is drawn', async () => {
  const { home, pending } = parked('prompt');

  const rendered = await draw(home, 5);
  for (const [i, out] of rendered.entries()) {
    assert.ok(out.includes(AD.headline), `render ${i} drew nothing`);
  }

  assert.deepEqual(
    billed(pending),
    [AD.requestId],
    'five renders of one decision did not bill exactly one impression',
  );
});

test('a slot with no filler recorded is treated as parked, and is not billed', async () => {
  // Every slot.json written before this field existed was a turn-end park --
  // that was the only filler there was. Guessing the other way would bill an
  // upgrade for ads it had already been paid for.
  const { home, pending } = parked('turn-end');
  const file = path.join(configDirOf(home), 'slot.json');
  const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
  delete raw.filler;
  fs.writeFileSync(file, JSON.stringify(raw), { mode: 0o600 });

  const [out] = await draw(home);
  assert.ok(out.includes(AD.headline), 'an older slot stopped rendering');
  assert.deepEqual(billed(pending), [], 'a slot from before fillers existed was billed');
});

test('a prompt-fetched ad that was not drawn is not billed', async () => {
  // Single-row mode with a status line of the user's own: theirs wins and ours
  // is never drawn. An advertiser must not pay for a row nobody saw.
  const { home, pending } = parked('prompt');
  const chain = path.join(home, 'mine.mjs');
  fs.writeFileSync(chain, "process.stdout.write('my own status line');\n");
  fs.writeFileSync(
    path.join(configDirOf(home), 'statusline-chain-claude.json'),
    JSON.stringify({ type: 'command', command: `"${process.execPath}" "${chain}"` }),
  );

  const res = await runStatusLine({
    args: ['--line'],
    stdin: JSON.stringify({ session_id: SESSION }),
    env: baseEnv({ HOME: home, CLAUDECODE: '1' }),
  });
  assert.equal(res.code, 0);
  assert.equal(res.stdout.trimEnd(), 'my own status line');
  assert.deepEqual(billed(pending), [], 'an ad that was never drawn was billed');
});

test('a fresher prompt fetch replaces a parked ad and brings its own bill', async () => {
  // The two fillers write the same file, so this is the ordinary sequence: a
  // turn ends and parks, the user types, the fetch lands and takes the slot.
  // Only the second one is owed.
  const { home, pending } = parked('turn-end');
  await draw(home, 2);
  assert.deepEqual(billed(pending), [], 'the parked ad was billed before the fetch even landed');

  const file = path.join(configDirOf(home), 'slot.json');
  fs.writeFileSync(
    file,
    JSON.stringify({
      ...AD,
      requestId: 'req_bill_fresh',
      headline: 'Fresher, matched to the prompt',
      clickUrl: 'https://ads.example/c/req_bill_fresh',
      sessionId: SESSION,
      filler: 'prompt',
      ts: Date.now(),
    }),
    { mode: 0o600 },
  );

  await draw(home, 3);
  assert.deepEqual(billed(pending), ['req_bill_fresh'], 'the wrong set of ads was billed');
});

test('nothing is billed while prmpt is disabled', async () => {
  // Opting out has to mean opting out of the money too. A claim recorded here
  // would be flushed to the backend by the next hook that runs -- an impression
  // reported for an ad that was deliberately never drawn.
  const { home, pending } = parked('prompt');
  const res = await runStatusLine({
    stdin: JSON.stringify({ session_id: SESSION }),
    env: baseEnv({ HOME: home, CLAUDECODE: '1', PRMPT_DISABLED: '1' }),
  });
  assert.equal(res.code, 0);
  assert.equal(res.stdout, '', 'a disabled install drew an ad');
  assert.deepEqual(billed(pending), [], 'a disabled install billed an impression');
});

// Reporting the impressions the status line has already drawn.
//
// The renderer bills locally -- it appends a requestId to pending.jsonl and
// returns, because it may not touch the network. Something else has to tell
// the backend, and that something is the next hook to run: turn-end.mjs when
// the turn finishes, or prompt-start.mjs when the next one begins.
//
// Neither of them may wait for it, so the flush happens in the same detached
// child that fetches status-line decisions, and both of those hooks are
// asserted here to have exited long before the request lands.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

import {
  LONG_TURN,
  TEST_TOKEN,
  assertSilentSuccess,
  baseEnv,
  configDirOf,
  decision,
  runHook,
  runPromptStart,
  stubServer,
  tmpDir,
  waitFor,
} from './helpers.mjs';

/** A stub that answers both mutations and records which was which. */
async function backend({ accept = true } = {}) {
  const server = await stubServer((body) => {
    const query = body?.query ?? '';
    if (query.includes('confirmImpressions')) {
      if (!accept) return { errors: [{ message: 'nope' }] };
      return { data: { confirmImpressions: body.variables.requestIds.length } };
    }
    return decision();
  });
  server.confirms = () =>
    server.requests.filter((r) => (r.body?.query ?? '').includes('confirmImpressions'));
  return server;
}

/** A HOME with impressions already rendered and awaiting confirmation. */
function homeWithPending(ids) {
  const home = tmpDir('prmpt-imp-home-');
  const dir = configDirOf(home);
  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  fs.writeFileSync(
    path.join(dir, 'pending.jsonl'),
    ids.map((requestId) => JSON.stringify({ requestId, at: new Date().toISOString() })).join('\n') + '\n',
    { mode: 0o600 },
  );
  return { home, pending: path.join(dir, 'pending.jsonl') };
}

test('the end-of-turn hook reports what the status line rendered', async () => {
  const { home, pending } = homeWithPending(['req_a', 'req_b']);
  const server = await backend();
  try {
    const res = await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: LONG_TURN }),
      env: baseEnv({ HOME: home, PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });
    assert.equal(res.code, 0);
    assert.equal(res.stderr, '');

    const confirm = await waitFor(() => server.confirms()[0] ?? null);
    assert.ok(confirm, 'the impressions were never reported');
    assert.deepEqual(confirm.body.variables.requestIds, ['req_a', 'req_b']);

    const drained = await waitFor(() => (fs.existsSync(pending) ? null : true));
    assert.ok(drained, 'confirmed impressions were not forgotten');
  } finally {
    await server.close();
  }
});

test('a turn too short to serve still reports what is owed', async () => {
  // The flush must not sit behind the ad path: most turns never reach it.
  const { home } = homeWithPending(['req_short']);
  const server = await backend();
  try {
    const res = await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: 'ok' }),
      env: baseEnv({ HOME: home, PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });
    assertSilentSuccess(res, 'short turn');
    const confirm = await waitFor(() => server.confirms()[0] ?? null);
    assert.ok(confirm, 'a short turn skipped the flush');
  } finally {
    await server.close();
  }
});

test('the next prompt reports them too', async () => {
  const { home } = homeWithPending(['req_c']);
  const server = await backend();
  try {
    const res = await runPromptStart({
      stdin: JSON.stringify({
        hook_event_name: 'UserPromptSubmit',
        session_id: 'sess-flush',
        prompt: 'why is the retry budget exhausted on cold starts',
      }),
      env: baseEnv({
        HOME: home,
        CLAUDECODE: '1',
        PRMPT_TOKEN: TEST_TOKEN,
        PRMPT_ENDPOINT: server.url,
      }),
    });
    assertSilentSuccess(res, 'prompt-start flush');
    const confirm = await waitFor(() => server.confirms()[0] ?? null);
    assert.ok(confirm, 'prompt-start skipped the flush');
    assert.deepEqual(confirm.body.variables.requestIds, ['req_c']);
  } finally {
    await server.close();
  }
});

test('a flush the backend refuses keeps the impressions for next time', async () => {
  // An unreported impression is money owed to the user. It is retried, never
  // dropped because one request failed.
  const { home, pending } = homeWithPending(['req_kept']);
  const server = await backend({ accept: false });
  try {
    await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: LONG_TURN }),
      env: baseEnv({ HOME: home, PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });
    const confirm = await waitFor(() => server.confirms()[0] ?? null);
    assert.ok(confirm, 'nothing was attempted');
    // Give the child time to have wrongly deleted the file before concluding.
    await new Promise((r) => setTimeout(r, 300));
    assert.ok(fs.existsSync(pending), 'a failed flush threw the impressions away');
    assert.match(fs.readFileSync(pending, 'utf8'), /req_kept/);
  } finally {
    await server.close();
  }
});

test('a turn with nothing pending spawns nothing and reports nothing', async () => {
  // This is every turn on almost every install, so it must cost a stat and no
  // more -- certainly not a process.
  const home = tmpDir('prmpt-imp-empty-');
  const server = await backend();
  try {
    await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: LONG_TURN }),
      env: baseEnv({ HOME: home, PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });
    await new Promise((r) => setTimeout(r, 400));
    assert.equal(server.confirms().length, 0, 'an empty pending log still called the backend');
  } finally {
    await server.close();
  }
});

// Backfilling a Base address onto an install that predates two-chain payouts.
//
// Every user created before ERC-20 payouts moved to Base has proven only a
// Solana address, so anything owed in USDC — the default — parks unsendable.
// Self-enrolment cannot fix it: that fires only when there is NO token, and
// these installs have one. Hence this path, and hence these tests.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { needsEvmLink, linkEvmInBackground } from '../hooks/lib/link-evm.mjs';

function tempHome() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'prmpt-linkevm-'));
  process.env.XDG_CONFIG_HOME = dir;
  return dir;
}

const LINKED = {
  token: 'a-token',
  solanaWallet: 'CJZsdW6RgwBxpN4M84RGm3MFzzBruCHL8SARz93Wm62M',
  endpoint: 'http://127.0.0.1:1',
};

test('needsEvmLink only fires for a linked install with no Base address', () => {
  assert.equal(needsEvmLink(LINKED), true);

  // Already linked: nothing to do, on every turn forever.
  assert.equal(needsEvmLink({ ...LINKED, evmWallet: '0xabc' }), false);
  // No token: that is enrolment's job, and doing both would race.
  assert.equal(needsEvmLink({ ...LINKED, token: '' }), false);
  // No recorded wallet: we cannot tell whose account this is, so we must not
  // attach an address to it.
  assert.equal(needsEvmLink({ ...LINKED, solanaWallet: undefined }), false);
  assert.equal(needsEvmLink(undefined), false);
});

test('it refuses when the key here is not the account it would link to', async () => {
  const home = tempHome();
  const { saveWallet, generateMnemonicWallet } = await import('../hooks/lib/wallet.mjs');

  // A dashboard-code install: a valid token for a wallet held somewhere else,
  // and a different key sitting on this machine. Linking would attach an
  // address we control to an account we do not — the exact thing proving a
  // wallet exists to prevent — so it must decline rather than "help".
  saveWallet(generateMnemonicWallet());
  assert.equal(linkEvmInBackground({ ...LINKED, solanaWallet: 'SomeoneElsesWalletAddress1111111111111111111' }), false);

  fs.rmSync(home, { recursive: true, force: true });
});

test('it does nothing when there is no wallet on this machine at all', async () => {
  const home = tempHome();
  // An install-code install with the key deliberately kept off the box.
  assert.equal(linkEvmInBackground(LINKED), false);
  fs.rmSync(home, { recursive: true, force: true });
});

test('it attempts once, then rate limits itself', async () => {
  const home = tempHome();
  const { saveWallet, walletFromMnemonic } = await import('../hooks/lib/wallet.mjs');

  // A phrase-backed install whose local key IS the account's identity.
  const wallet = walletFromMnemonic(
    'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about',
  );
  saveWallet(wallet);
  const config = { ...LINKED, solanaWallet: wallet.address };

  // The first call spawns (the CLI it detaches will fail against a dead
  // endpoint, which is fine and silent); the second is refused by the marker.
  // Without that marker every turn of an offline machine would spawn a child
  // forever, because each turn is a fresh process with no memory of the last.
  const first = linkEvmInBackground(config);
  const second = linkEvmInBackground(config);
  assert.equal(first, true);
  assert.equal(second, false, 'a second attempt inside the window must be refused');
  assert.equal(fs.existsSync(path.join(home, 'prmpt', '.evm-link-attempt')), true);

  fs.rmSync(home, { recursive: true, force: true });
});

test('PRMPT_NO_AUTO_ENROL=1 opts out of this too', async () => {
  const home = tempHome();
  const { saveWallet, walletFromMnemonic } = await import('../hooks/lib/wallet.mjs');
  const wallet = walletFromMnemonic(
    'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about',
  );
  saveWallet(wallet);

  process.env.PRMPT_NO_AUTO_ENROL = '1';
  try {
    // Somebody who opted out of a key being created for them has equally opted
    // out of one being registered for them.
    assert.equal(linkEvmInBackground({ ...LINKED, solanaWallet: wallet.address }), false);
  } finally {
    delete process.env.PRMPT_NO_AUTO_ENROL;
  }
  fs.rmSync(home, { recursive: true, force: true });
});

// The most important test in the suite.
//
// On Gemini CLI hooks run synchronously inside the agent loop, so a backend
// that accepts the connection and then never answers would stall the user's
// turn for as long as it felt like. The AbortController deadline is what
// stops that, and it is worth an explicit, timed assertion.

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  LONG_TURN,
  TEST_TOKEN,
  assertNoKeyLeak,
  assertSilentSuccess,
  baseEnv,
  runHook,
  stubServer,
} from './helpers.mjs';

test('a server that never responds is abandoned well inside 3s', async () => {
  const sockets = [];
  // Accept the request, read it fully, then simply never write a response.
  const server = await stubServer((_body, req) => {
    sockets.push(req.socket);
    return undefined; // handler wrote nothing and res is not ended: hang.
  });

  try {
    const res = await runHook({
      stdin: JSON.stringify({ hook_event_name: 'AfterAgent', prompt_response: LONG_TURN }),
      env: baseEnv({ PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });

    assertSilentSuccess(res, 'hanging server');
    assertNoKeyLeak(res, 'hanging server');
    assert.equal(server.requests.length, 1, 'the request should have reached the stub');

    // The hook's deadline is 1500ms; process spawn adds a little on top.
    assert.ok(
      res.ms < 3000,
      `hook took ${res.ms.toFixed(0)}ms; must abandon a hanging backend well under 3000ms`,
    );
    // And it must actually have waited for the deadline rather than bailing
    // early for some unrelated reason -- otherwise this test proves nothing.
    assert.ok(
      res.ms > 1000,
      `hook returned in ${res.ms.toFixed(0)}ms, which is too fast to have hit the 1500ms deadline`,
    );
    console.log(`  [timing] hanging-backend hook run: ${res.ms.toFixed(0)}ms (deadline 1500ms)`);
  } finally {
    for (const s of sockets) s.destroy();
    await server.close();
  }
});

test('PRMPT_TIMEOUT_MS shortens the deadline', async () => {
  const sockets = [];
  const server = await stubServer((_body, req) => {
    sockets.push(req.socket);
    return undefined;
  });
  try {
    const res = await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: LONG_TURN }),
      env: baseEnv({
        PRMPT_TOKEN: TEST_TOKEN,
        PRMPT_ENDPOINT: server.url,
        PRMPT_TIMEOUT_MS: '200',
      }),
    });
    assertSilentSuccess(res, 'short deadline');
    assert.ok(res.ms < 1500, `hook took ${res.ms.toFixed(0)}ms with a 200ms deadline`);
    console.log(`  [timing] 200ms-deadline hook run: ${res.ms.toFixed(0)}ms`);
  } finally {
    for (const s of sockets) s.destroy();
    await server.close();
  }
});

test('a slow-but-inside-the-deadline response is still used', async () => {
  const server = await stubServer((_body, _req, res) => {
    setTimeout(() => {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({
        data: {
          serveAd: {
            requestId: 'r-slow',
            headline: 'Slow but punctual',
            body: '',
            clickUrl: 'https://ads.example/c/r-slow',
          },
        },
      }));
    }, 300);
    return undefined;
  });
  try {
    const res = await runHook({
      stdin: JSON.stringify({ hook_event_name: 'Stop', last_assistant_message: LONG_TURN }),
      env: baseEnv({ PRMPT_TOKEN: TEST_TOKEN, PRMPT_ENDPOINT: server.url }),
    });
    assert.equal(res.code, 0);
    assert.equal(res.stderr, '');
    assert.match(res.stdout, /Slow but punctual/);
  } finally {
    await server.close();
  }
});

// Local tokenisation of the user's prompt.
//
// This module is the entire privacy story of the status-line surface. The
// prompt itself never leaves the machine: what goes over the wire is a sorted
// bag of individual keywords, from which the sentence cannot be rebuilt.
//
// These are unit tests on a pure function because the property being asserted
// -- "this text does not survive this transformation" -- is a property of the
// transformation, and is much easier to pin down here than through a process
// boundary. hooks/prompt-start.mjs is tested at the process boundary too.

import test from 'node:test';
import assert from 'node:assert/strict';

import { signalTokens } from '../hooks/lib/tokens.mjs';

test('a prompt becomes lowercased keywords with the stopwords removed', () => {
  const tokens = signalTokens('Please fix the flaky Postgres integration test');
  assert.deepEqual(tokens, ['fix', 'flaky', 'integration', 'postgres', 'test']);
});

test('the tokens are sorted, so the sentence cannot be reconstructed', () => {
  // Order is the last thing that carries the prompt's meaning as prose. Sorting
  // is what turns "a list of the words you typed, in order" into a bag.
  const tokens = signalTokens('zebra apple monkey');
  assert.deepEqual(tokens, ['apple', 'monkey', 'zebra']);
});

test('a distinctive phrase never survives as a phrase', () => {
  // Sorting can leave two words next to each other by coincidence, so the
  // property worth asserting is not "no pair survives" -- it is that the
  // PROMPT'S order is gone and the sentence itself is nowhere in the output.
  const phrase = 'nightingale acquisition closes before the quarterly restructure';
  const tokens = signalTokens(phrase);
  assert.ok(!JSON.stringify(tokens).includes(phrase), 'the phrase survived verbatim');
  assert.ok(!tokens.join(' ').includes('nightingale acquisition'), 'the prompt order survived');
  assert.deepEqual(tokens, [...tokens].sort(), 'the tokens are not sorted');
});

test('duplicates collapse', () => {
  assert.deepEqual(signalTokens('cache cache CACHE Cache'), ['cache']);
});

test('very short and very long words are dropped', () => {
  const tokens = signalTokens(`a bc ${'x'.repeat(60)} defg`);
  assert.deepEqual(tokens, ['bc', 'defg']);
});

test('the list is capped', () => {
  const many = Array.from({ length: 200 }, (_, i) => `word${i}`).join(' ');
  const tokens = signalTokens(many);
  assert.ok(tokens.length <= 32, `expected at most 32 tokens, got ${tokens.length}`);
});

// --- the things that must never become a token ------------------------------

test('fenced code blocks are removed before tokenising', () => {
  const tokens = signalTokens('speed this up\n```\nconst apiSecret = "hunter2";\n```\n');
  assert.ok(tokens.includes('speed'));
  for (const leaked of ['apisecret', 'hunter2', 'const']) {
    assert.ok(!tokens.includes(leaked), `code block leaked: ${leaked}`);
  }
});

test('an unterminated fence takes everything after it', () => {
  // A prompt that opens a code block and never closes it is common -- the
  // paste got truncated, or the model is mid-sentence. Treating the remainder
  // as prose would ship the whole snippet.
  const tokens = signalTokens('look at this\n```js\nconst apiSecret = "hunter2";\n');
  assert.ok(tokens.includes('look'));
  assert.ok(!tokens.includes('apisecret'));
  assert.ok(!tokens.includes('hunter2'));
});

test('inline code spans are removed before tokenising', () => {
  const tokens = signalTokens('why does `SUPER_SECRET_VALUE` break the build');
  assert.ok(tokens.includes('build'));
  assert.ok(!tokens.includes('super_secret_value'));
  assert.ok(!tokens.includes('super'));
});

test('URLs, paths and email addresses are removed whole', () => {
  const tokens = signalTokens(
    'check https://internal.acme.example/secret-plan and /home/janedoe/keys.txt ' +
    'then mail jane.doe@acme.example about deploys',
  );
  assert.ok(tokens.includes('deploys'), 'ordinary words still survive');
  for (const leaked of ['internal', 'acme', 'janedoe', 'keys', 'jane', 'doe', 'secret', 'plan', 'home']) {
    assert.ok(!tokens.includes(leaked), `identifier leaked: ${leaked}`);
  }
});

test('Windows paths are removed too', () => {
  const tokens = signalTokens('open C:\\Users\\JaneSmith\\secrets.env please');
  assert.ok(tokens.includes('open'));
  assert.ok(!tokens.includes('janesmith'));
  assert.ok(!tokens.includes('users'));
});

test('high-entropy blobs that look like secrets are dropped', () => {
  const tokens = signalTokens(
    'rotate the key 9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a and redeploy',
  );
  assert.deepEqual(tokens, ['key', 'redeploy', 'rotate']);
});

test('a token is never long enough to be a credential', () => {
  // Assembled at runtime on purpose. Spelling a live-key-shaped literal into a
  // file in a PUBLIC repo trips GitHub's push protection -- and it would be
  // indistinguishable from a real leak to anyone reading the history later.
  const secret = 'Zq7Xm2Rt9Vb4Nh6Kd1Ls8Pw3Cy5Ge0Ja';
  const credentialShaped = ['sk', 'live', secret].join('_');
  const tokens = signalTokens(`token ${credentialShaped}`);
  // The whole credential must be gone, not merely shortened -- assert that
  // directly rather than inferring it from a length bound, which a tokeniser
  // that split the key into harmless-looking chunks would also satisfy.
  assert.deepEqual(tokens, ['token'], `credential survived tokenisation: ${tokens}`);
  assert.ok(!tokens.some((t) => secret.toLowerCase().includes(t)), 'a fragment of the key survived');
  assert.ok(tokens.every((t) => t.length <= 24), `over-long token survived: ${tokens}`);
});

